export type { CreateBuildResult };

const fail = (status: number, json: Record<string, unknown>): CreateBuildResult => ({ ok: false, status, json });
const slotFail = (r: GameSlotRefusal): CreateBuildResult => fail(r.status, { error: r.error, code: r.code, ...(r.limit !== undefined ? { used: r.used, limit: r.limit, upgrade: r.upgrade ?? null } : {}) });

/** `body` is the JSON the API takes: { prompt, mcVersion, changeRequest, baseBuildId, model, attachmentIds, retarget?, assets? }.
 *  `assets` (Cyrus R1) is only a REQUEST (["texture"] / { texture: true }); the plan gate decides. */
export async function createModBuild(user: User, body: Record<string, unknown>, opts: { /** the caller shows the plan screen (the Forge): a plan with blocked lanes needs body.planAck first */ requirePlanAck?: boolean } = {}): Promise<CreateBuildResult> {
  const prompt = String(body.prompt ?? "").trim();
  const mcVersion = String(body.mcVersion ?? MB_VERSIONS[0]);
  const changeRequest = body.changeRequest ? String(body.changeRequest).trim() : "";
  const baseBuildId = body.baseBuildId ? String(body.baseBuildId) : null;
  // Cyrus (optional, additive): the model picked in the composer and pasted images.
  if (body.model !== undefined && body.model !== "auto" && !isCyrusModel(body.model)) return fail(400, { error: "Pick Auto, Katara, Saka or Yakko." });
  const attachmentIds = Array.isArray(body.attachmentIds) ? body.attachmentIds.filter(isUploadId).slice(0, 4) : [];

  if (!(MB_VERSIONS as readonly string[]).includes(mcVersion)) return fail(400, { error: "Pick a Minecraft version from the list." });

  let base = null;
  if (baseBuildId) {
    base = await cyrusDb.modBuild.findUnique({ where: { id: baseBuildId } });
    if (!base || base.userId !== user.id) return fail(404, { error: "Not found" });
    if (base.status !== "succeeded") return fail(400, { error: "You can only change a build that has finished. Wait for it to finish, then ask for the change." });
    if (changeRequest.length < 4 || changeRequest.length > 2000) return fail(400, { error: "Describe the change in a few words (up to 2,000 characters)." });
  } else if (prompt.length < 12 || prompt.length > 4000) {
    return fail(400, { error: prompt.length < 12 ? "Tell us a bit more about what the plugin should do." : "That's a lot! Keep it under 4,000 characters." });
  }

  // Not a mod request (gibberish, "Yo Yo Yo", repetition, only symbols): refuse BEFORE tokens are held or the
  // AI is called. Free, instant, and never charged (lib/cyrus/prompt-check.ts).
  const unclear = promptProblem(base ? changeRequest : prompt);
  if (unclear) return fail(400, { error: unclear, code: "prompt_unclear" });

  // Cyrus admin (/admin/cyrus): an account suspended from building, or Minecraft switched off.
  if (await cyrusSuspension(user.id, "build")) return fail(403, { error: "Building is paused on this account, so nothing was started or charged. Open a support ticket if you think this is a mistake and we will look at it.", code: "suspended" });
  if (!(await cyrusGameBuildable("minecraft"))) return fail(503, { error: "Building for Minecraft is paused for a short while. Nothing was started or charged. Try again later.", code: "game_disabled" });
  if (await cyrusBuildsPaused()) return fail(503, { error: BUILDS_PAUSED_MESSAGE, code: "builds_paused" });
  { const cap = await checkSpendCaps(user.id); if (!cap.ok) return fail(cap.status, { error: cap.error, code: cap.code }); }
  // r51 storage (CYRUS_STORAGE): a full account starts no new build (fails closed); installs and downloads are never gated
  { const st = await checkStorageWrite(user.id, 0, "build"); if (!st.ok) return fail(st.status, { error: st.error, code: st.code }); }
  // D-63 game slots: a build in a game the account does not mod yet needs a free slot on its plan (hard: plan gating).
  // A game already in use (any change, any new mod in it) asks nothing. Checked again under a lock at the insert.
  const slot = await checkGameSlot(user, "minecraft");
  if (!slot.ok) return slotFail(slot);

  for (const [k, max, windowMs] of [["mb:create:min", 3, 60_000], ["mb:create:hour", 20, 3_600_000]] as const) {
    const rl = checkRateLimit(`${k}:${user.id}`, { max, windowMs });
    if (!rl.ok) return fail(429, { error: `You're building fast! Try again in ${rl.retryAfterSec}s.`, code: RATE_LIMITED, retryable: true, retryAfterSec: rl.retryAfterSec });
  }
  const inflight = await cyrusDb.modBuild.count({ where: { userId: user.id, status: { notIn: ["succeeded", "failed"] } } });
  if (inflight >= (await accountMaxActive())) return fail(429, { error: "You already have builds running. Wait for one to finish, or cancel it, then start this one.", code: ACCOUNT_BUSY, retryable: true });

  // Cyrus starter bank (CYRUS_STARTER_BANK): the customer picked the ready-made mod on the plan screen. Re-matched here (the
  // client's choice is never trusted), served by the build service with NO model call, charged the flat bank price.
  if (!base && bankOn() && body.bank && typeof body.bank === "object") return createBankBuild(user, { prompt, mcVersion, want: String((body.bank as { id?: unknown }).id ?? "") });

  // Live-test fix (F): the MOD PLAN decides the lanes BEFORE anything is held. A planned request (the plan screen's
  // approved lanes) is used as is; any other entry point gets the deterministic plan (rules, free) so every prompt gets
  // its plan-allowed, version-usable assets automatically. A lane the prompt needs but cannot get must be confirmed
  // first (planAck) when the caller can show the plan (the Forge), so no tokens are held for it.
  const planText = base ? changeRequest : prompt;
  const planVersion = base ? (body.retarget === true ? mcVersion : base.mcVersion) : mcVersion;
  const plannedReq = readPlannedRequest(body.assets);
  const legacyKinds = explicitAssetKinds(body.assets);
  const serverPlan = plannedReq ? null : await buildModPlan({ text: planText, game: "minecraft", mcVersion: planVersion, tier: await tierOf(user.id).catch(() => null), change: !!base,
    toggles: Object.fromEntries(legacyKinds.map((k) => [k, true])) }, { flags: hostFlags() });
  if (serverPlan) {
    const pre = preBuildCheck(serverPlan.plan, { requireAck: opts.requirePlanAck === true, ack: body.planAck });
    if (!pre.ok) return fail(pre.status, { ...pre.json, plan: serverPlan });
  }
  const assetsRequest = plannedReq ?? serverPlan!.assets;
  const plannedLanes = plannedReq ? plannedReq.lanes : builtLanes(serverPlan!.plan);
  const id = "mb" + randomBytes(10).toString("hex");
  // Cyrus tokens (lib/cyrus/tokens/builds.ts): pick the model the account may use and hold
  // tokens for this build before anything is created. A change keeps the model its version
  // was built with unless a new one is picked (or that model is no longer unlocked).
  const gate = await gateBuild({
    user, buildId: id,
    requested: isCyrusModel(body.model) ? body.model : undefined,
    baseModel: base ? readCyrusMeta(base.cyrus).model : undefined,
    text: base ? `${base.prompt}\n${changeRequest}` : prompt,
    // Live-test fix (C): "auto" (the default picker choice) = the cheapest capable model; the hold follows the planned lanes
    auto: body.model === "auto", lanes: plannedLanes, change: !!base,
  });
  if (!gate.ok) return fail(gate.status, { error: gate.error, code: gate.code, need: gate.need, available: gate.available, model: gate.model });
  const model = gate.model;
  // Cyrus R1 asset slice: the plan decides (server side, never the client) which custom assets this build may
  // generate. Nothing requested -> no lookups, no project, no `assets` field: the request below is unchanged.
  const rootBuildId = base ? (base.rootBuildId ?? base.id) : id;
  const svcPlanner = ((await svcHealthCached().catch(() => null))?.features as { planner?: unknown } | undefined)?.planner === true;
  const assets = await resolveBuildAssets({
    userId: user.id, rootBuildId, change: !!base, explicit: assetsRequest, text: base ? changeRequest : prompt, plannerSource: plannedReq ? (body.plannerSource === "planner" ? "planner" : "rules") : "rules",
    mcVersion: base ? (body.retarget === true ? mcVersion : base.mcVersion) : mcVersion,
    existing: base ? existingAssetKinds(base.result) : [], existingDatapack: base ? hasDatapacks(base.result) : false, existingDesign: base ? hasDesigns(base.result) : false, existingGameplay: base ? hasGameplayDesigns(base.result) : false, existingBosses: base ? hasBossDesigns(base.result) : false, existingHud: base ? hasHudDesigns(base.result) : false, existingMotion: base ? hasMotionDesigns(base.result) : false, existingWorldgen: base ? hasWorldgenDatapacks(base.result) : false, existingItemModels: base ? hasItemModels(base.result) : false, existingArmor: base ? hasLaneSpec(base.result, "armor") : false, existingBlocks: base ? hasLaneSpec(base.result, "blocks") : false, title: null,
  }, { ...assetRequestDeps, servicePlanner: () => svcPlanner });
  // Cyrus catalog tools (CYRUS_CATALOG_TOOLS, off): a pre-gated asset pool the model can search in the build. Off = null
  // before any lookup, and the request below is unchanged.
  const catalog = await catalogOfferForBuild({ userId: user.id, text: base ? `${base.prompt}\n${changeRequest}` : prompt }, {
    tierOf: (uid) => tierOf(uid), serviceSupports: async () => ((await svcHealthCached())?.features as { catalogTools?: unknown } | undefined)?.catalogTools === true,
    // R42 DEV ONLY: dev-foundation rows for preview (owner) accounts when the dev store gate passes (never production)
    foundation: async () => {
      const { loadFoundation, foundationTools } = await import("@/lib/cyrus/gameassets/foundation.server");
      const f = loadFoundation();
      if (!f) return null;
      const { getHost } = await import("@/lib/cyrus/host");
      return (await getHost().access.isPreviewUser(user, "modbuilder").catch(() => false)) ? foundationTools(f) : null;
    },
  });
  const cyrus: CyrusMeta | null = model || attachmentIds.length || assets.meta ? { ...(model ? { model } : {}), ...(assets.meta ? { assets: assets.meta } : {}) } : null;
  const createRow = async (c: CyrusDb) => { const r = await c.modBuild.create({
    data: {
      id,
      userId: user.id,
      prompt: base ? base.prompt : prompt,
      changeRequest: base ? changeRequest : null,
      baseBuildId: base ? base.id : null,
      rootBuildId,
      // A change keeps its base's version, unless it is a RETARGET (Cyrus lifecycle: "Update with
      // Cyrus for the new version"), which rebuilds the same mod for another supported version.
      mcVersion: base ? (body.retarget === true ? mcVersion : base.mcVersion) : mcVersion,
      pluginName: base ? base.pluginName : null,
      ...(cyrus ? { cyrus } : {}),
