  return r; };
  // D-63: the row that takes a game slot is inserted under the per-account lock (two concurrent first builds in two
  // new games cannot both take the last slot); a lost race gives the held tokens back.
  let row: Awaited<ReturnType<typeof createRow>>;
  if (slot.takesSlot) {
    const claim = await withGameSlot(user, "minecraft", createRow);
    if (!claim.ok) {
      if (gate.tracked) await releaseBuildTokens(id);
      // the asset gate may already have attached an (empty) engine project to this never-created chain: drop it so it
      // does not hold the game's slot
      await cyrusDb.cyrusProject.deleteMany({ where: { rootBuildId: id, userId: user.id, revisionCount: 0 } }).catch(() => undefined);
