      id,
      prompt: row.prompt,
      mcVersion: row.mcVersion,
      // A fork copy ("Build on this mod") is based on the ORIGINAL build the service holds.
      ...(base ? { baseBuildId: await serviceBuildId(base.id), changeRequest } : {}),
      ...(model ? { tier: model } : {}),
      ...(images.length ? { images } : {}),
      ...(assets.service ? { assets: assets.service } : {}),
      ...(catalog ? { catalog } : {}),
