async function headOf(userId: string, rootId: string): Promise<string | null> {
  const rows = await cyrusDb.modBuild.findMany({ where: { userId, OR: [{ id: rootId }, { rootBuildId: rootId }] }, orderBy: { createdAt: "asc" } });
  const root = rows.find((r) => r.id === rootId);
  if (!root) return null;
  const ok = rows.filter((r) => r.status === "succeeded");
  const want = readCyrusMeta(root.cyrus).headBuildId;
  return (want && ok.find((r) => r.id === want)?.id) || ok[ok.length - 1]?.id || null;
}

export async function POST(req: Request) {
  const user = await modBuilderUser();
  if (!user) return NOT_FOUND();
  let body: Omit<ForgeRequest, "model"> & { model: ForgeRequest["model"] | "auto"; attachmentIds?: unknown; mcVersion?: unknown; retarget?: unknown; assets?: unknown; planAck?: unknown; plannerSource?: unknown; bank?: unknown };
  try {
    body = (await req.json()) as typeof body;
  } catch {
    return NextResponse.json({ error: "Invalid JSON body" }, { status: 400 });
  }
  if (!body?.prompt || typeof body.prompt !== "string" || !body.prompt.trim()) return NextResponse.json({ error: "Prompt is required" }, { status: 400 });
  if (body.model !== "auto" && !MODEL_BY_ID[body.model]) return NextResponse.json({ error: "Pick Auto, Katara, Saka or Yakko." }, { status: 400 });
  body.games = cleanGames(body.games);
  const prompt = body.prompt.trim();
  // Gibberish and non-requests are refused on EVERY path, before routing, before any tokens, before any model.
  const unclear = promptProblem(prompt);
  if (unclear) return NextResponse.json({ error: unclear, code: "prompt_unclear" }, { status: 400 });
  const ctx = body.context ?? {};

  // Real or template?
  const refineReal = isRealModId(ctx.modId);
  // A change to a template mod stays on its template game, whatever the prompt mentions.
  const refineTemplate = !!ctx.modId && !refineReal;
  const route = refineReal || refineTemplate ? null : routePrompt(prompt, ctx, [...GAMES, ...body.games]);
  const real = refineReal || !!(route && GAME_BY_ID[route.gameId]?.real);

  if (real) {
    let baseBuildId: string | null = null;
    if (refineReal) {
      baseBuildId = await headOf(user.id, rootOfRealMod(ctx.modId!));
      if (!baseBuildId) return NextResponse.json({ error: "This mod has no version that built yet. Forge it again, or wait for the running build." }, { status: 400 });
    }
    const r = await createModBuild(user, {
      ...(baseBuildId ? { baseBuildId, changeRequest: prompt } : { prompt }),
      ...(typeof body.mcVersion === "string" ? { mcVersion: body.mcVersion } : {}),
      // Cyrus lifecycle: "Update with Cyrus for the new version" rebuilds the mod for mcVersion.
      ...(refineReal && body.retarget === true ? { retarget: true } : {}),
      model: body.model,
      attachmentIds: body.attachmentIds,
      // Cyrus R1: a REQUEST for custom assets (["texture"]); the server-side plan gate decides (lib/cyrus/assets/request.ts).
      // Live-test fix (F): or the plan screen's approved lanes ({ plan: 1, lanes }), with planAck once the user pressed
      // "Continue anyway" for lanes that cannot be built here (nothing is held before that).
      ...(body.assets !== undefined ? { assets: body.assets } : {}),
      ...(body.planAck === true ? { planAck: true } : {}),
      ...(body.plannerSource === "planner" ? { plannerSource: "planner" } : {}),
      // Cyrus starter bank (CYRUS_STARTER_BANK): the ready-made mod picked on the plan screen (re-matched server side)
      ...(!refineReal && body.bank && typeof body.bank === "object" ? { bank: body.bank } : {}),
    }, { requirePlanAck: true });
    if (!r.ok) return r.status === 404 ? NOT_FOUND() : NextResponse.json(r.json, { status: r.status });
    return ndjson((signal) => followBuild(r.build.id, { userId: user.id, refining: refineReal, signal }), req);
  }

  // NO BUILDER for this game yet. The handoff's template generator used to run here and hand back a made-up mod for a game
  // Cyrus cannot build for; that is not what a customer expects from a studio, so it is switched off. The studio shows the
  // game as "coming soon" and the dock refuses before this point; this is the server-side backstop.
  const named = (route && [...GAMES, ...body.games].find((g) => g.id === route.gameId)?.name) || ([...GAMES, ...body.games].find((g) => g.id === ctx.gameId)?.name) || "That game";
  return NextResponse.json({ error: `${named} support is coming soon. Cyrus builds Minecraft plugins today, and nothing was built or charged.`, code: "game_not_ready" }, { status: 409 });
  // eslint-disable-next-line no-unreachable
  return ndjson(async function* (signal) {
    for await (const ev of forgeStream(body as ForgeRequest, signal)) yield ev.type === "start" ? { ...ev, credits: 0, real: false } : ev;
  }, req);
}

export async function GET(req: Request) {
  const user = await modBuilderUser();
  if (!user) return NOT_FOUND();
  const id = new URL(req.url).searchParams.get("follow") || "";
  if (!/^[A-Za-z0-9_-]{1,64}$/.test(id)) return NextResponse.json({ error: "Bad build id" }, { status: 400 });
  const row = await cyrusDb.modBuild.findUnique({ where: { id } });
  if (!row || row.userId !== user.id) return NOT_FOUND();
  return ndjson((signal) => followBuild(id, { userId: user.id, refining: !!row.baseBuildId, signal }), req);
}
