// Infinite Dungeon staged run through the REAL portal path (2026-10-15). Fresh build for stage 1, REFINES (baseBuildId+changeRequest)
// of the previous succeeded build afterwards. Honours every gate; never bypasses.
//   NODE_PATH=/opt/nxeon/node_modules npx tsx scripts/cyrus/qa-dungeon.ts stage <n> --user <id> --out <dir> [--prompt-file f] [--fix "text"]
//   ... status --out <dir>
import fs from "node:fs";
import path from "node:path";
import { cyrusDb } from "../../lib/cyrus/db";
import { db } from "../../lib/db";
import { modBuilderAccess } from "../../lib/modbuilder/access";
import { createModBuild } from "../../lib/modbuilder/create";
import { analyzeNeeds, buildModPlan, type PlannerDeps } from "../../lib/cyrus/planner/run";
import { svcHealthCached, svcPlan } from "../../lib/cyrus/builder/client";
import { analyzePrompt } from "../../lib/cyrus/coach/analyze";
import { coachOn } from "../../lib/cyrus/coach/flags";
import { techniquesOn } from "../../lib/cyrus/designer/spec";
import { changeLaneDefaults } from "../../lib/cyrus/coach/plan-hook";
import { tierOf, tokensActiveFor } from "../../lib/cyrus/tokens/access";
import { loadTokenConfig } from "../../lib/cyrus/tokens/config";
import { MB_VERSIONS } from "../../lib/modbuilder/types";

const argv = process.argv.slice(2);
const cmd = argv[0];
const opt = (n: string, d = "") => { const i = argv.indexOf(`--${n}`); return i >= 0 ? argv[i + 1] : d; };
const out = opt("out"); if (!out) throw new Error("--out required");
fs.mkdirSync(out, { recursive: true });
const jp = path.join(out, "journal.json");
type J = { stage: number; kind: "stage" | "fix"; buildId: string | null; baseBuildId: string | null; prompt: string; submittedAt: string; plan?: unknown; coach?: unknown; refused?: unknown; availBefore: number };
const readJ = (): J[] => (fs.existsSync(jp) ? JSON.parse(fs.readFileSync(jp, "utf8")) : []);
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const TERMINAL = ["succeeded", "failed"];
const avail = async (u: string) => { const a = await cyrusDb.cyrusTokenAccount.findUnique({ where: { userId: u } }); return a ? a.balance - a.reserved : 0; };

async function stage() {
  const n = Number(argv[1]); const userId = opt("user"); const fix = opt("fix");
  const user = await db.user.findUnique({ where: { id: userId } });
  if (!user) throw new Error("no such user");
  if (!(await modBuilderAccess(user))) throw new Error("no Cyrus access");
  const stages = JSON.parse(fs.readFileSync(path.join(__dirname, "qa-dungeon-prompts.json"), "utf8"));
  const text = fix || stages.find((s: any) => s.stage === n).prompt;
  const j = readJ();
  const mcVersion = MB_VERSIONS[0];
  const cfg = await loadTokenConfig().catch(() => null);
  const metered = cfg ? await tokensActiveFor(user, cfg).catch(() => false) : false;
  const tier = await tierOf(userId, cfg ?? undefined).catch(() => null);
  const deps: PlannerDeps = { ask: (b) => svcPlan(b), supports: async () => ((await svcHealthCached())?.features as { planner?: unknown } | undefined)?.planner === true };
  const before = await avail(userId);
  const floor = Number(opt("floor", "2500"));
  if (before < floor) { console.log(`STOP: available ${before} < floor ${floor}`); return; }
  // base = last succeeded build in the journal
  let base: string | null = null;
  if (n > 1 || fix) {
    const prev = [...j].reverse().find((x) => x.buildId);
    if (!prev) throw new Error("no previous build in journal");
    const row = await cyrusDb.modBuild.findUnique({ where: { id: prev.buildId! } });
    if (!row || row.status !== "succeeded") throw new Error(`previous build ${prev.buildId} is ${row?.status}, not succeeded`);
    base = prev.buildId;
  }
  const change = !!base;
  // planner exactly as POST /api/cyrus/plan (change + coach hook)
  const pre = await analyzeNeeds({ text, game: "minecraft", mcVersion }, deps);
  const toggles: Record<string, boolean> = {};
  let held: any[] = [];
  if (coachOn() && change) { held = changeLaneDefaults(text, pre.lanes, toggles as any); for (const l of held) toggles[l] = false; }
  const plan = await buildModPlan({ text, game: "minecraft", mcVersion, tier, change, toggles: toggles as any, cfg: metered ? cfg : null, needs: pre.lanes, source: pre.source, meta: { costUsd: pre.costUsd, ms: pre.ms, error: pre.error } }, deps);
  const coach = coachOn() ? analyzePrompt({ text, version: mcVersion, change: change ? { name: "The Infinite Dungeon", summary: null, paths: [] } : null, lanes: plan.plan.lanes, held, techniques: techniquesOn() }) : null;
  const body: Record<string, unknown> = { ...(base ? { baseBuildId: base, changeRequest: text } : { prompt: text }), mcVersion, model: "auto", assets: plan.assets, plannerSource: plan.planner.source === "planner" ? "planner" : "rules", ...(plan.plan.mustConfirm ? { planAck: true } : {}) };
  const t0 = Date.now();
  const r = await createModBuild(user, body, { requirePlanAck: true });
  const row: J = { stage: n, kind: fix ? "fix" : "stage", buildId: r.ok ? r.build.id : null, baseBuildId: base, prompt: text, submittedAt: new Date(t0).toISOString(), availBefore: before,
    plan: { lanes: plan.plan.lanes, mustConfirm: plan.plan.mustConfirm, source: plan.planner.source, assets: plan.assets, held }, coach: coach ? { score: (coach as any).score, gaps: (coach as any).gaps } : null };
